test("not.to.have.jsonBody fails when body matches", function() {
  const body = res.getBody();
  let failed = false;
  try {
    expect(body).not.to.have.jsonBody("hello");
  } catch (e) {
    failed = true;
  }
  expect(failed).to.be.true;
});

